head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.gAcptNo;
scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R
scwin.vScrenID = "ULDSTF08066.xml";
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
};
scwin.fn_get_code = function() {
    //etn발행사		
    dts_EtnInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_EtnInst.Reset();
    dts_EtnSrty.DataID = "/etn/EtnCodeAct.do?method=listSrtyCd&For=R";
    dts_EtnSrty.Reset();
};
scwin.fn_search = function() {
    var url = "/etn/EtnStatMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchIsurSrtyCreditDetailList";
    url += "&inputMessageId=ETN_ISUR_SRTY_CREDIT_INOUT&outputMessageId=ETN_ISUR_SRTY_CREDIT_INOUT";
    url += "&ISUR_SRTY_CD=" + cbo_inst_srty.BindColVal;
    url += "&GUBUN=" + rdo_gubun.getValue();
    url += "&S_DATE=" + $c.stf.getObjectValue(edt_SDate);
    url += "&E_DATE=" + $c.stf.getObjectValue(edt_EDate);
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd_list);
};
scwin.fn_PopCreditDetail = function(row) {
    //frame.CreateDialogFrame("ULDSTF08061",".ULDSTF08061.gfm", "영업용순자본비율", 30, 50, 430, 575, "window");
    if (dts.getCellData(eval(row), "ACPT_NO") == "") return;
    //2017-11-27 KBoY 비공개 첨부서류 볼 수 없음.
    $c.stf.fn_OpenDisclViewer(dts.setCellData(eval(row, function(edtSDate, edtEDate) {
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        edtSDate.setValue($c.ut.cGetMinusYear(vCurDate, 3));
        edtEDate.setValue(vCurDate);
    }, function() {
        if (rdo_gubun.getValue() == "2") {
            cbo_inst_srty.setDisabled(true);
            cbo_inst_srty.ComboDataID = "dts_EtnInst";
        } else if (rdo_gubun.getValue() == "3") {
            cbo_inst_srty.setDisabled(true);
            cbo_inst_srty.ComboDataID = "dts_EtnSrty";
        } else if (rdo_gubun.getValue() == "1") cbo_inst_srty.setDisabled(true);
        cbo_inst_srty.setSelectedIndex(0);
        scwin.fn_search();
    }, function() {
        /*		if( cbo_inst_srty.index == 0 ) {
        			alert(getMessageParam("MSG-0016", ""));
        			cbo_inst_srty.focus();
        			return ;
        		}
        */
        scwin.fn_search();
    }, function() {
        $c.stf.alert_error(dts);
    }, function(rowcount) {
        txb_TotCnt.setValue("총건수 : " + rowcount);
        //	FillGridHeaderTotalCnt(rowcount, panel_page);
        //	FillGridHeaderTotalCnt(rowcount);
        $c.cm.CloseWin(rowcount, grd_list);
    }, function(row, colid) {
        scwin.fn_PopCreditDetail(row);
    }, function() {
        $c.pre_newlisting.fn_initSearchDate(edt_SDate, edt_EDate);
        var usrCBData = "1주일전^1,1개월전^2,3개월전^3,6개월전^4,1년전^5,2년전^6";
        cmb_PeriodTp.CBData = usrCBData; //사용자CBData 지정

        rdo_gubun.setValue("1");
        scwin.fn_get_code();
        scwin.fn_search();
    }, function() {
        scwin.fn_search();
    }, function() {
        window.close();
    }, function() {
        popUpCalendar2(edt_SDate);
    }, function() {
        popUpCalendar2(edt_EDate);
    }, function() {
        var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
    })));
};
